// The Executive Overview = the executive dashboard (ADR-0037 §2, §8; D-106 (c): one read model and one operation;
// REQ-S03-009, REQ-S13-001 "executive", REQ-S13-002; M0101):
//   GET /overview?organizationId=&transformationId=&ownerUserId=&periodId=&phase=&status=
// The six T10 areas over the transformations of the organization the caller may read, narrowed by the filters (M0101's
// tiles map one-to-one: outcomes -> Outcomes, value -> Value, critical initiatives -> Portfolio, adoption -> People &
// adoption, blockers -> Dependencies, decisions -> Decisions), plus one row per transformation with its six area
// statuses. 404 when the caller holds no transformation.read grant in the organization or names a transformation it
// may not read; 422 dashboard.period_not_found / dashboard.owner_not_found. A read model: nothing stored.
import type { ExecutiveOverview } from "@mth/shared/schemas";
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { principalOf } from "../access/index.ts";
import { parseQuery, type ModuleDeps } from "../platform/index.ts";
import {
  areaStatuses,
  computeAreas,
  factsOfTransformation,
  loadAreaDefinitions,
  loadDashboardContext,
  presentAreas,
  readOnly,
} from "./dashboards/engine.ts";
import { appliedFilters, asIdList, organizationFilterShape, resolveFilters } from "./dashboards/filters.ts";
import { readableTransformations } from "./dashboards/scope.ts";

export const EXECUTIVE_OVERVIEW = "/api/v1/overview";
const overviewQuery = z.strictObject(organizationFilterShape);

/** Registers this file's routes and returns them as "METHOD /path". */
export function registerExecutiveOverviewRoutes(app: FastifyInstance, { db }: ModuleDeps): string[] {
  app.get(
    EXECUTIVE_OVERVIEW,
    { config: { access: { permission: "transformation.read" } } },
    async (request): Promise<ExecutiveOverview> => {
      const query = parseQuery(overviewQuery, request.query);
      const transformationIds = asIdList(query.transformationId);
      return readOnly(db, async (tx) => {
        const scope = await readableTransformations(tx, principalOf(request), query.organizationId, {
          transformationIds,
          phase: query.phase ?? null,
          status: query.status ?? null,
        });
        const filters = await resolveFilters(tx, {
          organizationId: query.organizationId,
          transformationIds,
          ownerUserId: query.ownerUserId,
          periodId: query.periodId,
          phase: query.phase,
          status: query.status,
        });
        const ctx = await loadDashboardContext(tx, scope, filters);
        const areas = presentAreas(ctx, computeAreas(ctx.facts, ctx.clock, ctx.policy), await loadAreaDefinitions(tx), {
          drillTransformationIds: transformationIds,
          workstream: false,
        });
        return {
          organizationId: query.organizationId,
          generatedAt: ctx.generatedAt,
          businessDate: filters.businessDate,
          appliedFilters: appliedFilters(filters),
          transformationCount: scope.length,
          areas,
          transformations: scope.map((t) => ({
            transformationId: t.id,
            code: t.code,
            name: t.name,
            areaStatuses: areaStatuses(computeAreas(factsOfTransformation(ctx.facts, t.id), ctx.clock, ctx.policy)),
          })),
        };
      });
    },
  );
  return [`GET ${EXECUTIVE_OVERVIEW}`];
}
// The Template 10 Executive Transformation Dashboard of one transformation (ADR-0037 §2-§5; REQ-PB-062, REQ-PB-063,
// REQ-PB-064, REQ-S13-001 "transformation", REQ-S13-002):
//   GET /transformations/{t}/dashboard[?ownerUserId=&periodId=]   transformation.read; 404 outside the scope
// The six areas, each with its own status rule, headlines that drill to their contributing records, and items. A read
// model: computed in the request, nothing stored.
import type { TransformationDashboard } from "@mth/shared/schemas";
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { principalOf } from "../../access/index.ts";
import { parse, parseQuery, type ModuleDeps } from "../../platform/index.ts";
import { computeAreas, loadAreaDefinitions, loadDashboardContext, presentAreas, readOnly } from "./engine.ts";
import { appliedFilters, resolveFilters, transformationFilterQuery } from "./filters.ts";
import { dashboardRestriction, withoutRestrictedItems } from "./restricted.ts";
import { readableTransformation } from "./scope.ts";

export const TRANSFORMATION_DASHBOARD = "/api/v1/transformations/:transformationId/dashboard";
const tParams = z.strictObject({ transformationId: z.uuid() });

export function registerTransformationDashboardRoutes(app: FastifyInstance, { db }: ModuleDeps): string[] {
  app.get(
    TRANSFORMATION_DASHBOARD,
    { config: { access: { permission: "transformation.read" } } },
    async (request): Promise<TransformationDashboard> => {
      const { transformationId } = parse(tParams, request.params, "params");
      const query = parseQuery(transformationFilterQuery, request.query);
      return readOnly(db, async (tx) => {
        const principal = principalOf(request);
        const t = await readableTransformation(tx, principal, transformationId);
        const filters = await resolveFilters(tx, {
          organizationId: t.organizationId,
          transformationIds: [t.id],
          ownerUserId: query.ownerUserId,
          periodId: query.periodId,
        });
        const ctx = await loadDashboardContext(tx, [t], filters);
        // P6 (T-DG6-BE-B2; ADR-0051 §2): same figures for every reader; restricted records are not listed.
        const restriction = await dashboardRestriction(tx, principal, ctx.facts);
        const presented = presentAreas(
          ctx,
          computeAreas(ctx.facts, ctx.clock, ctx.policy),
          await loadAreaDefinitions(tx),
          {
            drillTransformationIds: [t.id],
            workstream: false,
          },
        );
        const areas = withoutRestrictedItems(presented, restriction);
        return {
          transformationId: t.id,
          generatedAt: ctx.generatedAt,
          businessDate: filters.businessDate,
          timezone: filters.timezone,
          appliedFilters: appliedFilters(filters),
          areas,
          ...restriction.field,
        };
      });
    },
  );
  return [`GET ${TRANSFORMATION_DASHBOARD}`];
}
// The workstream dashboard (ADR-0037 §2; ADR-0038 §9; REQ-S13-001 "workstream", REQ-S13-002):
//   GET /transformations/{t}/workstreams/{w}/dashboard[?ownerUserId=&periodId=]   transformation.read
// Scope: the active initiatives of one workstream. Outcomes = the outcomes those initiatives contribute to, Value = the
// benefits allocated to them (each counted once), Portfolio = those initiatives, Dependencies = dependencies to or
// from them. Decisions and People & adoption are transformation-level: not_applicable with rule key
// dashboard.rag.workstream_not_applicable. A workstream outside the readable transformation is 404; an archived one
// 422 dashboard.workstream_archived (exact ADR-0037 §13 text). A read model: nothing stored.
import type { WorkstreamDashboard } from "@mth/shared/schemas";
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { principalOf } from "../../access/index.ts";
import { parse, parseQuery, problems, type ModuleDeps } from "../../platform/index.ts";
import { loadWorkstreamFacts } from "../../portfolio/index.ts";
import {
  computeAreas,
  factsOfWorkstream,
  loadAreaDefinitions,
  loadDashboardContext,
  presentAreas,
  readOnly,
} from "./engine.ts";
import { appliedFilters, dashboardRefusal, resolveFilters, transformationFilterQuery } from "./filters.ts";
import { dashboardRestriction, withoutRestrictedItems } from "./restricted.ts";
import { readableTransformation } from "./scope.ts";

export const WORKSTREAM_DASHBOARD = "/api/v1/transformations/:transformationId/workstreams/:workstreamId/dashboard";
const wsParams = z.strictObject({ transformationId: z.uuid(), workstreamId: z.uuid() });

export function registerWorkstreamDashboardRoutes(app: FastifyInstance, { db }: ModuleDeps): string[] {
  app.get(
    WORKSTREAM_DASHBOARD,
    { config: { access: { permission: "transformation.read" } } },
    async (request): Promise<WorkstreamDashboard> => {
      const { transformationId, workstreamId } = parse(wsParams, request.params, "params");
      const query = parseQuery(transformationFilterQuery, request.query);
      return readOnly(db, async (tx) => {
        const principal = principalOf(request);
        const t = await readableTransformation(tx, principal, transformationId);
        const ws = await loadWorkstreamFacts(tx, t.id, workstreamId);
        if (!ws) throw problems.notFound();
        if (ws.status === "archived") throw dashboardRefusal("dashboard.workstream_archived", "");
        const filters = await resolveFilters(tx, {
          organizationId: t.organizationId,
          transformationIds: [t.id],
          ownerUserId: query.ownerUserId,
          periodId: query.periodId,
        });
        const ctx = await loadDashboardContext(tx, [t], filters);
        const narrowed = { ...ctx, facts: factsOfWorkstream(ctx.facts, ws.initiativeIds) };
        // P6 (T-DG6-BE-B2; ADR-0051 §2): same figures for every reader; restricted records are not listed.
        const restriction = await dashboardRestriction(tx, principal, narrowed.facts);
        const presented = presentAreas(
          narrowed,
          computeAreas(narrowed.facts, ctx.clock, ctx.policy),
          await loadAreaDefinitions(tx),
          { drillTransformationIds: [t.id], workstream: true },
        );
        const areas = withoutRestrictedItems(presented, restriction);
        return {
          workstreamId: ws.workstreamId,
          transformationId: t.id,
          code: ws.code,
          name: ws.name,
          generatedAt: ctx.generatedAt,
          businessDate: filters.businessDate,
          appliedFilters: appliedFilters(filters),
          areas,
          ...restriction.field,
        };
      });
    },
  );
  return [`GET ${WORKSTREAM_DASHBOARD}`];
}

