  type DashboardMetric,
  type DashboardValue,
  type DrilldownEvidence,
  type DrilldownInput,
  type DrilldownItem,
} from "@mth/shared/schemas";
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { loadBenefitLineEvidence } from "../../benefits/index.ts";
import { principalOf } from "../../access/index.ts";
import { loadKpiStatusLineage } from "../../kpi/index.ts";
import {
  cursorSchema,
  decodeCursor,
  encodeCursor,
  filterHash,
  limitSchema,
  parseQuery,
  problems,
  type ModuleDeps,
} from "../../platform/index.ts";
import {
  basisClasses,
  basisOfClass,
  countValue,
  gapValue,
  kpiActualValue,
  knownValue,
  NO_PROFIT_AND_CASH,
  notApplicableValue,
  RATIO_ROUNDING,
  sumValue,
  unknownValue,
  valueCurrencies,
  valueLinesOf,
  type BasisGap,
  type ValueBenefitFact,
  type ValueCurrencyLine,
} from "./areas.ts";
import {
  computeAreas,
  initiativeValue,
  kpiStatusHref,
  loadDashboardContext,
  readOnly,
  T_PATH,
  type AreaResults,
  type DashboardContext,
} from "./engine.ts";
import { appliedFilters, asIdList, dashboardRefusal, organizationFilterShape, resolveFilters } from "./filters.ts";
import { benefitInClass, extraStateLinesOf, isExtraState, lineEntersClassSum } from "./finance.ts";
