403 apps/api/test/integration/access/sensitive-reach-sweep.test.ts
// The class sweep for a sensitive benefit's identity and values (T-DG6-BE-Z5; F-DG6-300, F-DG6-280; ADR-0051 §2 and
// its 2026-11-04 amendment; REQ-S10-002 "a sensitive benefit is hidden from a workstream member without the grant";
// M0188), against a scratch database of the run's disposable PostgreSQL seeded with the REAL synthetic demo dataset
// (ADR-0050). Everything is SYNTHETIC: an illustrative example, not Mobily actual performance. Marking a record
// sensitive or granting access is an access decision, never a business approval (G1-G6), and nothing here names or
// touches the engineering gates DG0-DG7.
//
// Ported from the code-security probe zz-cs-r4-sens-sweep.test.ts (round 4) and widened from the 128
// `{transformationId}`-only operations to EVERY GET operation of docs/api/openapi.yaml whose path parameters can be
// filled from the seeded data (each `{xId}` from a row of its table, preferring a row of the sensitive benefit; the
// report definition codes and gate codes expanded), plus the live registers reports, a report snapshot generated by an
// ADMITTED user, the inbox and the executive-decision reads.
//
// One demo benefit gets a unique title and a distinctive planned value (with their audit event); the worker's corrective
// consumer opens its variance case (titled with the benefit's title, as before marking); a TO marks the benefit
// sensitive; an admitted TL records the case red in two review cycles and the worker's blocker escalation creates the
// executive ask and its owner's notification. Then, for every operation:
//   - negative: TL and AUD at the transformation (no grant, not a named party) never receive the title, the
//     "<code> <title>" label or the planned value in any response body (any status);
//   - positive control: a second TL with an explicit grant (admitted) does receive them on the benefit's own reads,
//     the benefit list, the traceability graph, the live register and the stored snapshot (the demo benefit has its
//     upstream links, so the missing-links item is covered by sensitive-reach-derived.test.ts),
//     so the sweep would notice a fix that simply removed the data for everyone.
// The resolved operation count has a floor, so a contract change that silently drops operations from the sweep fails.
import { insertAuditEvent, migrate, seedDemo, sql } from "@mth/db";
import { afterAll, beforeAll, describe, expect, inject, it } from "vitest";
import { DEMO_ANCHORS } from "../../../../../packages/db/src/demo/data/kpis.ts";
import { createScratchDatabase, dropScratchDatabase, roleUrl } from "../../../../../packages/db/test/helpers.ts";
import { REPORT_DEFINITION_CODES, REPORT_REGISTERS } from "../../../../../packages/shared/src/schemas/report.ts";
import { operations } from "../../support/contract.ts";
import { call, createUser, grant, signIn, startApi, type Session, type TestApi } from "../../support/harness.ts";
import { handleBlockerEscalation } from "../../../../worker/src/handlers/escalations.ts";
import { handleBenefitVariance } from "../../../../worker/src/handlers/raid.ts";
import { businessToday, plusDays } from "../governance/meeting-fixtures.ts";
import { envelopeOf } from "../governance/t16-fixtures.ts";
import { randomUUID } from "node:crypto";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Body = any;

const T = DEMO_ANCHORS.transformationId;
const ORG = DEMO_ANCHORS.organizationId;
const TITLE = "Synthetic CONFIDENTIAL BE-Z5 sweep benefit";
const PLANNED = "7654321.1234";

let api: TestApi;
let scratch: string | null = null;
let to: Session;
let tl: Session;
let aud: Session;
let admitted: Session;
const S = { benefitId: "", code: "", snapshotIds: [] as string[], caseId: "", meetingId: "", askId: "" };

const get = (path: string, session: Session) => call<Body>(api.app, "GET", path, { session, contract: false });

beforeAll(async () => {
  const { adminUrl } = inject("mthDb");
  scratch = await createScratchDatabase(adminUrl, "mth_be_z5_sweep");
  await migrate(roleUrl(adminUrl, scratch, "mth_owner"));
  await seedDemo(roleUrl(adminUrl, scratch, "mth_owner"), {
    mthEnv: "demo",
    runKind: "seed",
    requestedVia: "cli",
    requestedBy: null,
  });
  api = await startApi({ database: scratch, env: { MTH_ENV: "demo" } });
  const grantor = DEMO_ANCHORS.users.sp;
  const scope = { type: "transformation" as const, id: T };
  const mk = async (role: string, s: { type: "organization" | "transformation"; id: string }) => {
    const u = await createUser(api.db, ORG);
    await grant(api.db, grantor, u.id, role, s, ORG);
    return u;
  };
  const uTo = await mk("TO", { type: "organization", id: ORG });
  const uTl = await mk("TL", scope);
  const uAud = await mk("AUD", scope);
  const uAdm = await mk("TL", scope);
  to = await signIn(api.app, uTo.subject);
  tl = await signIn(api.app, uTl.subject);
  aud = await signIn(api.app, uAud.subject);
  admitted = await signIn(api.app, uAdm.subject);

  const b = await api.db
    .selectFrom("benefit")
    .select(["id", "code", "version"])
    .where("transformation_id", "=", T)
    .where("status", "=", "active")
    .orderBy("code")
    .executeTakeFirstOrThrow();
  S.benefitId = b.id;
  S.code = b.code;
  // Synthetic setup: a unique title and a distinctive planned value, with the audit event the 0004 guard requires.
  await api.db.transaction().execute(async (tx) => {
    await sql`UPDATE benefit SET title = ${TITLE}, planned_value = ${PLANNED}::numeric, version = version + 1,
                     updated_at = now() WHERE id = ${b.id}::uuid`.execute(tx);
    await insertAuditEvent(
      tx,
      { actorType: "user", actorUserId: grantor, requestId: `be-z5-sweep-${b.id}`, source: "api" },
      {
        action: "benefit.update",
        recordType: "benefit",
        recordId: b.id,
        organizationId: ORG,
        transformationId: T,
        priorVersion: b.version,
        newVersion: b.version + 1,
      },
    );
  });
  // Before marking: the worker's corrective consumer opens (or updates) the benefit's variance case, titled with the
  // benefit's title as in DG4 (a case opened before its benefit is marked keeps that title: the worst case below).
  const variance = await handleBenefitVariance(
    api.db,
    {
      outboxEventId: randomUUID(),
      eventType: "benefit.variance_evaluated",
      schemaVersion: 1,
      idempotencyKey: `benefit.variance_evaluated:be-z5-sweep-${randomUUID()}`,
      organizationId: ORG,
      payload: {
        benefitId: b.id,
        measurementId: randomUUID(),
        periodStart: "2026-09-01",
        periodEnd: "2026-09-28",
        plannedAmount: "100000.0000",
        measuredAmount: "80000.0000",
        variance: "-20000.0000",
        offTrack: true,
      },
    },
    "be-z5-sweep",
  );
  S.caseId = (variance.signal as Body)?.correctiveCaseId ?? "";
  expect(S.caseId, JSON.stringify(variance)).not.toBe("");
  const mark = await call<Body>(api.app, "PUT", `/api/v1/transformations/${T}/records/benefit/${b.id}/sensitivity`, {
    session: to,
    headers: { "if-match": '"0"' },
    body: { isSensitive: true, reason: "Synthetic commercially sensitive benefit" },
  });
  expect(mark.status, JSON.stringify(mark.body)).toBe(200);
  const g = await call<Body>(api.app, "POST", "/api/v1/admin/sensitive-grants", {
    session: to,
    body: { transformationId: T, recordType: "benefit", recordId: b.id, granteeUserId: uAdm.id, reason: "Synthetic" },
  });
  expect(g.status, JSON.stringify(g.body)).toBe(201);
  // The admitted TL runs two review cycles that record the case red; the worker's blocker escalation creates the ask
  // (and its owner's notification) that every transformation reader can read.
  const base = `/api/v1/transformations/${T}`;
  const forum = await call<Body>(api.app, "POST", `${base}/forums`, {
    session: to,
    body: {
      nameEn: "Synthetic review BE-Z5 sweep",
      nameAr: "منتدى اصطناعي",
      cadenceLabel: "Weekly",
      purpose: "Synthetic",
      participantsLabel: "Synthetic",
      outputsLabel: "RAID",
      outputKinds: ["raid"],
    },
  });
  expect(forum.status, JSON.stringify(forum.body).slice(0, 400)).toBe(201);
  // The red-cycles rule counts working days on the organization's default business calendar (Asia/Riyadh default).
  const hasCalendar = await api.db
    .selectFrom("business_calendar")
    .select("id")
    .where("organization_id", "=", ORG)
    .where("is_default", "=", true)
    .where("status", "=", "active")
    .executeTakeFirst();
  if (hasCalendar === undefined) {
    const adm = await mk("ADM_TECH", { type: "organization", id: ORG });
    const cal = await call<Body>(api.app, "POST", `/api/v1/organizations/${ORG}/calendars`, {
      session: await signIn(api.app, adm.subject),
      body: { code: "CALBEZ5", nameEn: "Synthetic calendar", nameAr: "تقويم اصطناعي", isDefault: true },
    });
    expect(cal.status, JSON.stringify(cal.body).slice(0, 400)).toBe(201);
  }
  const today = await businessToday(api);
  for (const d of [1, 8]) {
    const m = await call<Body>(api.app, "POST", `${base}/meetings`, {
      session: admitted,
      body: { forumId: forum.body.id, scheduledDate: plusDays(today, d), startTime: "09:00", durationMinutes: 60 },
    });
    expect(m.status, JSON.stringify(m.body).slice(0, 400)).toBe(201);
    const st = await call<Body>(api.app, "POST", `${base}/meetings/${m.body.id}/start`, {
      session: admitted,
      headers: { "if-match": '"1"' },
    });
    expect(st.status).toBe(200);
    const r = await call<Body>(api.app, "POST", `${base}/meetings/${m.body.id}/blocker-statuses`, {
      session: admitted,
      body: { sourceRecordType: "corrective_case", sourceRecordId: S.caseId, rag: "red" },
    });
    expect(r.status, JSON.stringify(r.body).slice(0, 400)).toBe(201);
    S.meetingId = m.body.id;
    const esc = await handleBlockerEscalation(api.db, await envelopeOf(api.db, r.body.id), "be-z5-sweep");
    console.log(`[BE-Z5 sweep] blocker escalation ${d}: ${JSON.stringify(esc)}`);
  }
  const ask = await api.db
    .selectFrom("decision")
    .select("id")
    .where("blocker_record_id", "=", S.caseId)
    .executeTakeFirst();
  expect(ask, "the blocker escalation created an ask").toBeDefined();
  S.askId = ask!.id;
  // Snapshots generated by the ADMITTED reader (they hold the benefit's row when stored).
  for (const register of ["benefits", "kpis"] as const) {
    const r = await call<Body>(api.app, "POST", `/api/v1/transformations/${T}/reports/registers/generate`, {
      session: admitted,
      body: { parameters: { register } },
      contract: false,
    });
    expect(r.status, JSON.stringify(r.body).slice(0, 400)).toBe(201);
    S.snapshotIds.push(r.body.id);
  }
}, 600_000);

afterAll(async () => {
  await api?.close();
  if (scratch !== null) await dropScratchDatabase(inject("mthDb").adminUrl, scratch);
}, 60_000);

const snake = (s: string) => s.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

/** Table-name overrides for path parameters whose table is not `snake(name without Id)`. */
const TABLE_OF: Readonly<Record<string, string>> = {
  decisionId: "decision",
  snapshotId: "report_snapshot",
  submissionNo: "",
  approvalId: "approval",
  ruleId: "automation_rule",
  calendarId: "business_calendar",
  assessmentFormId: "assessment_form",
  assignmentId: "scoped_assignment",
  groupId: "access_group",
  grantId: "sensitive_record_grant",
  auditEventId: "audit_event",
  kpiActualId: "kpi_actual",
  versionId: "methodology_version",
  updateId: "status_update",
  workItemId: "work_item",
  taskId: "work_item",
  digestId: "digest",
  exportId: "export_job",
  importId: "import_job",
  connectorId: "connector",
  conversationId: "assistant_conversation",
  savedViewId: "saved_view",
};

/** Fills one path parameter from the seeded data (a row of the sensitive benefit first), or null. */
async function valueOf(
  name: string,
  tables: ReadonlySet<string>,
  columns: Map<string, Set<string>>,
): Promise<string[]> {
  switch (name) {
    case "transformationId":
      return [T];
    case "organizationId":
      return [ORG];
    case "businessUnitId":
      return [DEMO_ANCHORS.businessUnitId];
    case "userId":
      return [DEMO_ANCHORS.users.bo];
    case "benefitId":
    case "recordId":
    case "allocationTargetId":
      return [S.benefitId];
    case "recordType":
    case "allocationTargetType":
      return ["benefit"];
    case "gateCode":
      return ["G1", "G2", "G3", "G4", "G5", "G6"];
    case "definitionCode":
      return [...REPORT_DEFINITION_CODES];
    case "versionNo":
    case "submissionNo":
    case "snapshotNo":
      return ["1"];
    case "snapshotId":
      return [...S.snapshotIds];
    case "correctiveCaseId":
      return [S.caseId];
    case "meetingId":
      return [S.meetingId];
    case "decisionId":
      return [S.askId];
    default:
      break;
  }
  if (!name.endsWith("Id")) return [];
  const table = TABLE_OF[name] ?? snake(name.slice(0, -2));
  if (table === "" || !tables.has(table)) return [];
  const cols = columns.get(table) ?? new Set<string>();
  const out: string[] = [];
  if (cols.has("benefit_id")) {
    const r = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)}
      WHERE benefit_id = ${S.benefitId}::uuid ORDER BY id LIMIT 1`.execute(api.db);
    out.push(...r.rows.map((x) => x.id));
  }
  const where = cols.has("transformation_id") ? sql`WHERE transformation_id = ${T}::uuid` : sql``;
  const r = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)} ${where}
    ORDER BY id LIMIT 1`.execute(api.db);
  for (const x of r.rows) if (!out.includes(x.id)) out.push(x.id);
  if (out.length === 0) {
    // Nothing of this table in the demo transformation: any row of the database (an organization-level record).
    const any = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)} ORDER BY id LIMIT 1`.execute(
      api.db,
    );
    out.push(...any.rows.map((x) => x.id));
  }
  return out;
}

/** Every concrete GET path of the contract that the seeded data can fill, plus the explicit extra reads. */
async function sweepPaths(): Promise<{ resolved: { id: string; path: string }[]; skipped: string[] }> {
  const cols = await sql<{ table_name: string; column_name: string }>`
    SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public'`.execute(api.db);
  const columns = new Map<string, Set<string>>();
  for (const c of cols.rows) columns.set(c.table_name, (columns.get(c.table_name) ?? new Set()).add(c.column_name));
  const tables = new Set(columns.keys());
  const cache = new Map<string, string[]>();
  const resolved: { id: string; path: string }[] = [];
  const skipped: string[] = [];
  for (const o of operations) {
    if (o.method !== "GET") continue;
    const params = [...o.path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]!);
    let paths = [o.path];
    let ok = true;
    for (const p of params) {
      if (!cache.has(p)) cache.set(p, await valueOf(p, tables, columns));
      const values = cache.get(p)!;
      if (values.length === 0) {
        ok = false;
        break;
      }
      paths = paths.flatMap((x) => values.map((v) => x.replace(`{${p}}`, v)));
    }
    if (!ok) {
      skipped.push(o.operationId);
      continue;
    }
    for (const path of paths) resolved.push({ id: o.operationId, path });
  }
  const t = `/api/v1/transformations/${T}`;
  for (const register of REPORT_REGISTERS)
    resolved.push({
      id: `getLiveReport(registers: ${register})`,
      path: `${t}/reports/registers/live?parameters=${encodeURIComponent(JSON.stringify({ register }))}`,
    });
  resolved.push({ id: "searchRecords(title)", path: `/api/v1/search?q=${encodeURIComponent("CONFIDENTIAL BE-Z5")}` });
  resolved.push({ id: "listMyInbox(all)", path: "/api/v1/me/inbox?limit=100" });
  return { resolved, skipped };
}

const leaksOf = (text: string): string[] =>
  [TITLE, `${S.code} ${TITLE}`, PLANNED].filter((needle) => text.includes(needle));

describe("ADR-0051 §2: a sensitive benefit's title, code-with-title and values over every GET (F-DG6-300 class)", () => {
  it("control: TL and AUD get 404 on the benefit; the admitted TL and the TO read it", async () => {
    const item = `/api/v1/transformations/${T}/benefits/${S.benefitId}`;
    expect((await get(item, tl)).status).toBe(404);
    expect((await get(item, aud)).status).toBe(404);
    const a = await get(item, admitted);
    expect(a.status).toBe(200);
