const snake = (s: string) => s.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);

/** Table-name overrides for path parameters whose table is not `snake(name without Id)`. */
const TABLE_OF: Readonly<Record<string, string>> = {
  decisionId: "decision",
  snapshotId: "report_snapshot",
  submissionNo: "",
  approvalId: "approval",
  ruleId: "automation_rule",
  calendarId: "business_calendar",
  assessmentFormId: "assessment_form",
  assignmentId: "scoped_assignment",
  groupId: "access_group",
  grantId: "sensitive_record_grant",
  auditEventId: "audit_event",
  kpiActualId: "kpi_actual",
  versionId: "methodology_version",
  updateId: "status_update",
  workItemId: "work_item",
  taskId: "work_item",
  digestId: "digest",
  exportId: "export_job",
  importId: "import_job",
  connectorId: "connector",
  conversationId: "assistant_conversation",
  savedViewId: "saved_view",
};

/** Fills one path parameter from the seeded data (a row of the sensitive benefit first), or null. */
async function valueOf(
  name: string,
  tables: ReadonlySet<string>,
  columns: Map<string, Set<string>>,
): Promise<string[]> {
  switch (name) {
    case "transformationId":
      return [T];
    case "organizationId":
      return [ORG];
    case "businessUnitId":
      return [DEMO_ANCHORS.businessUnitId];
    case "userId":
      return [DEMO_ANCHORS.users.bo];
    case "benefitId":
    case "recordId":
    case "allocationTargetId":
      return [S.benefitId];
    case "recordType":
    case "allocationTargetType":
      return ["benefit"];
    case "gateCode":
      return ["G1", "G2", "G3", "G4", "G5", "G6"];
    case "definitionCode":
      return [...REPORT_DEFINITION_CODES];
    case "versionNo":
    case "submissionNo":
    case "snapshotNo":
      return ["1"];
    case "snapshotId":
      return [...S.snapshotIds];
    case "correctiveCaseId":
      return [S.caseId];
    case "meetingId":
      return [S.meetingId];
    case "decisionId":
      return [S.askId];
    default:
      break;
  }
  if (!name.endsWith("Id")) return [];
  const table = TABLE_OF[name] ?? snake(name.slice(0, -2));
  if (table === "" || !tables.has(table)) return [];
  const cols = columns.get(table) ?? new Set<string>();
  const out: string[] = [];
  if (cols.has("benefit_id")) {
    const r = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)}
      WHERE benefit_id = ${S.benefitId}::uuid ORDER BY id LIMIT 1`.execute(api.db);
    out.push(...r.rows.map((x) => x.id));
  }
  const where = cols.has("transformation_id") ? sql`WHERE transformation_id = ${T}::uuid` : sql``;
  const r = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)} ${where}
    ORDER BY id LIMIT 1`.execute(api.db);
  for (const x of r.rows) if (!out.includes(x.id)) out.push(x.id);
  if (out.length === 0) {
    // Nothing of this table in the demo transformation: any row of the database (an organization-level record).
    const any = await sql<{ id: string }>`SELECT id::text AS id FROM ${sql.table(table)} ORDER BY id LIMIT 1`.execute(
      api.db,
    );
    out.push(...any.rows.map((x) => x.id));
  }
  return out;
}

/** Every concrete GET path of the contract that the seeded data can fill, plus the explicit extra reads. */
async function sweepPaths(): Promise<{ resolved: { id: string; path: string }[]; skipped: string[] }> {
  const cols = await sql<{ table_name: string; column_name: string }>`
    SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public'`.execute(api.db);
  const columns = new Map<string, Set<string>>();
  for (const c of cols.rows) columns.set(c.table_name, (columns.get(c.table_name) ?? new Set()).add(c.column_name));
  const tables = new Set(columns.keys());
  const cache = new Map<string, string[]>();
  const resolved: { id: string; path: string }[] = [];
  const skipped: string[] = [];
  for (const o of operations) {
    if (o.method !== "GET") continue;
    const params = [...o.path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]!);
    let paths = [o.path];
    let ok = true;
    for (const p of params) {
      if (!cache.has(p)) cache.set(p, await valueOf(p, tables, columns));
      const values = cache.get(p)!;
      if (values.length === 0) {
        ok = false;
        break;
      }
      paths = paths.flatMap((x) => values.map((v) => x.replace(`{${p}}`, v)));
    }
    if (!ok) {
      skipped.push(o.operationId);
      continue;
    }
    for (const path of paths) resolved.push({ id: o.operationId, path });
  }
  const t = `/api/v1/transformations/${T}`;
  for (const register of REPORT_REGISTERS)
    resolved.push({
      id: `getLiveReport(registers: ${register})`,
      path: `${t}/reports/registers/live?parameters=${encodeURIComponent(JSON.stringify({ register }))}`,
    });
  resolved.push({ id: "searchRecords(title)", path: `/api/v1/search?q=${encodeURIComponent("CONFIDENTIAL BE-Z5")}` });
  resolved.push({ id: "listMyInbox(all)", path: "/api/v1/me/inbox?limit=100" });
  return { resolved, skipped };
}

const leaksOf = (text: string): string[] =>
  [TITLE, `${S.code} ${TITLE}`, PLANNED].filter((needle) => text.includes(needle));

describe("ADR-0051 §2: a sensitive benefit's title, code-with-title and values over every GET (F-DG6-300 class)", () => {
  it("control: TL and AUD get 404 on the benefit; the admitted TL and the TO read it", async () => {
    const item = `/api/v1/transformations/${T}/benefits/${S.benefitId}`;
    expect((await get(item, tl)).status).toBe(404);
    expect((await get(item, aud)).status).toBe(404);
    const a = await get(item, admitted);
    expect(a.status).toBe(200);
    expect(a.body.title).toBe(TITLE);
    expect((await get(item, to)).status).toBe(200);
  });

  it("TL and AUD (not admitted) never receive the title, the code-with-title or the planned value; the admitted TL does", async () => {
    const { resolved, skipped } = await sweepPaths();
    console.log(`[BE-Z5 sweep] ${resolved.length} requests per reader; ${skipped.length} operations not fillable`);
    console.log(`[BE-Z5 sweep] not fillable: ${skipped.join(" ")}`);
    // A floor: the contract has 446 GET operations at HEAD; most of them must stay in the sweep.
    expect(new Set(resolved.map((r) => r.id)).size).toBeGreaterThan(330);
    const leaks: string[] = [];
    const seenByAdmitted = new Set<string>();
    for (const op of resolved) {
      for (const [who, s] of [
        ["TL", tl],
        ["AUD", aud],
      ] as const) {
        const r = await get(op.path, s);
        const found = leaksOf(typeof r.body === "string" ? r.body : JSON.stringify(r.body));
        if (found.length > 0) leaks.push(`${who} ${op.id} ${r.status} ${op.path} -> ${found.join(" | ")}`);
      }
      const a = await get(op.path, admitted);
      const text = typeof a.body === "string" ? a.body : JSON.stringify(a.body);
      if (text.includes(TITLE)) seenByAdmitted.add(op.id);
    }
    if (leaks.length > 0) console.log(`[BE-Z5 sweep] leaks:\n${leaks.join("\n")}`);
    expect(leaks).toEqual([]);
    for (const id of [
      "getBenefit",
      "listBenefits",
      "getTraceability",
      "getLiveReport(registers: benefits)",
      "getReportSnapshot",
    ])
      expect(seenByAdmitted, `the admitted reader sees the title on ${id}`).toContain(id);
  }, 1_800_000);
});

